#define M_PI (3.1415926535897932384626433832795)
#define HIT_DISTANCE (0.008)
#define VERY_FAR (9999.0)
#define MAX_RAYMARCH_STEPS (128)

float dot2( in vec2 v ) { return dot(v,v); }
float dot2( in vec3 v ) { return dot(v,v); }
float ndot( in vec2 a, in vec2 b ) { return a.x*b.x - a.y*b.y; }


// https://www.shadertoy.com/view/WslGWl
float hash(float n)
{
    return fract(sin(n) * 43758.5453);
}

vec2 random2(vec2 st){
    st = vec2( dot(st,vec2(127.1,311.7)), dot(st,vec2(269.5,183.3)) );
    return -1.0 + 2.0 * fract(sin(st) * 7.);
}

///
/// Noise function
///
float noise2(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    // smootstep
    vec2 u = f*f*(3.0-2.0*f);

    return mix( mix( dot( random2(i + vec2(0.0,0.0) ), f - vec2(0.0,0.0) ),
                     dot( random2(i + vec2(1.0,0.0) ), f - vec2(1.0,0.0) ), u.x),
                mix( dot( random2(i + vec2(0.0,1.0) ), f - vec2(0.0,1.0) ),
                     dot( random2(i + vec2(1.0,1.0) ), f - vec2(1.0,1.0) ), u.x), u.y);
}

float noise3(in vec3 x)
{
    vec3 p = floor(x);
    vec3 f = fract(x);

    f = f * f * (3.0 - 2.0 * f);

    float n = p.x + p.y * 57.0 + 113.0 * p.z;

    float res = mix(mix(mix(hash(n +   0.0), hash(n +   1.0), f.x),
                        mix(hash(n +  57.0), hash(n +  58.0), f.x), f.y),
                    mix(mix(hash(n + 113.0), hash(n + 114.0), f.x),
                        mix(hash(n + 170.0), hash(n + 171.0), f.x), f.y), f.z);
    return res;
}

mat3 m = mat3( 0.00,  0.80,  0.60,
              -0.80,  0.36, -0.48,
              -0.60, -0.48,  0.64);

///
/// Fractal Brownian motion.
///
/// Refer to:
/// EN: https://thebookofshaders.com/13/
/// JP: https://thebookofshaders.com/13/?lan=jp
///


float fbm2(vec2 coord) {
	float value = 0.0;
	float scale = 0.2;
	for (int i = 0; i < 4; i++) {
		value += noise2(coord) * scale;
		coord *= 2.0;
		scale *= 0.5;
	}
	return value + 0.2;
}


float fbm3(vec3 p)
{
    float f;
    f  = 0.5000 * noise3(p); p = m * p * 2.02;
    f += 0.2500 * noise3(p); p = m * p * 2.03;
    f += 0.1250 * noise3(p);
    return f;
}


struct Light
{
    vec3 pos;
    vec3 color;
};

struct Material
{
    vec3 color;
};

struct SceneQueryResult
{
    float distToNearestObj;
    Material nearestObjMaterial;
};

struct RayMarchResult
{
    float rayTravelDistance;
    vec3 color;
};

float opSmoothUnion(float d1, float d2, float k)
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

// SDF of a sphere
// p: point; c: sphere center; r: sphere radius
float sdSphere(in vec3 p, in vec3 c, float r)
{
    return length(p - c) - r;
}


float sdMetaSphere(in vec3 p, in vec3 c, float r)
{
    float tt = iTime * 0.15;
    vec3 seed = vec3(tt + 14.6, tt + 57.1, tt + 35.3);
    vec3 ones = vec3(1.0, 0.0, 0.0);

    vec3 offset = vec3(0.0, cos(tt * 0.28), 0.0) * 0.2;
    vec3 offset1 = vec3(0.0, 0.0 + sin(tt * 0.77 + M_PI / 4.0), -0.16) * 0.27;
    vec3 offset2 = vec3(-0.11, 0.0 + sin(tt * 1.14 + M_PI / 7.0), 0.18) * 0.09;
    vec3 offset3 = vec3(0.09, -0.01 + sin(tt * 1.06 + M_PI / 3.0), 0.1) * 0.14;
    vec3 offset4 = vec3(0.07, -0.25 + cos(tt * 0.65 + M_PI / 3.0), -0.05) * 0.44;

    return opSmoothUnion(
            sdSphere(p, c + offset + offset1, r * 0.98),
            opSmoothUnion(
                sdSphere(p, c + offset + offset2, r * 1.27),
                opSmoothUnion(
                    sdSphere(p, c + offset + offset3, r * 0.95),
                    sdSphere(p, c + offset + offset4, r * 0.8),
                    0.1),
                0.14),
            0.16);
}

// p: point; h: capsule height; r: capsule radius
float sdVerticalCapsule(in vec3 p, float h, float r)
{
    p.y -= clamp(p.y, 0.0, h);
    return length(p) - r;
}

// p: point
// b : bounds
float sdBox(in vec3 p, in vec3 b)
{
    vec3 q = abs(p) - b;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

SceneQueryResult scene(in vec3 p)
{
    SceneQueryResult res;
    res.distToNearestObj = VERY_FAR;
    res.nearestObjMaterial = Material(vec3(0.0));

    float sphere_0 = sdMetaSphere(p, vec3(0.0, 0.1, 0.0), 0.12);
    if (sphere_0 < res.distToNearestObj)
    {
        res.distToNearestObj = sphere_0;
        res.nearestObjMaterial = Material(vec3(1.0, 0.4, 0.0));
    }

    return res;
}

vec3 sceneNormal(in vec3 p)
{
    const vec3 eps = vec3(0.001, 0.0, 0.0);
    float dx = scene(p + eps.xyy).distToNearestObj - scene(p - eps.xyy).distToNearestObj;
    float dy = scene(p + eps.yxy).distToNearestObj - scene(p - eps.yxy).distToNearestObj;
    float dz = scene(p + eps.yyx).distToNearestObj - scene(p - eps.yyx).distToNearestObj;
    vec3 normal = vec3(dx, dy, dz);
    return normalize(normal);
}

RayMarchResult rayMarch(in vec3 ro, in vec3 rd)
{
    RayMarchResult res;
    res.rayTravelDistance = -1.0;
    res.color = vec3(0.0);

    float travelledDistance = 0.0;

    for (int i = 0; i < MAX_RAYMARCH_STEPS; i++)
    {
        vec3 p = ro + travelledDistance * rd;

        SceneQueryResult probe = scene(p);

        if (probe.distToNearestObj < HIT_DISTANCE)
        {
            vec3 hitNormal = sceneNormal(p);
            float rim = 1.12 - max(0.0, -dot(hitNormal, rd));
            vec3 objectColor = probe.nearestObjMaterial.color;
            vec3 lightDir = vec3(0.0, 1.0, 0.2);
            vec3 lightColor = vec3(1.0, 0.9, 0.0);
            vec3 fresnelColor = vec3(0.72, 0.1, 0.0);
            vec3 baseColor = mix(objectColor, lightColor, clamp(-dot(lightDir, hitNormal) + 0.23, 0.0, 1.0));
            res.color = mix(baseColor, fresnelColor, pow(rim, 4.0));
            break;
        }
        else
        {
            travelledDistance += probe.distToNearestObj;
        }
    }

    return res;
}

#define AA 2


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float cameraZ = -3.5;
    vec3 finalColor = vec3(0.0);
    vec2 p;

    #if AA > 0
    for (int m = 0; m < AA; m++)
    for (int n = 0; n < AA; n++)
    {
        vec2 o = vec2(float(m), float(n)) / float(AA) - 0.5;
        p = (-iResolution.xy + 2.0 * (fragCoord.xy + o)) / iResolution.y;
        #else
        p = (-iResolution.xy + 2.0 * fragCoord.xy) / iResolution.y;
        #endif

        vec3 ro = vec3(0.0, 0.0, cameraZ);
        vec3 rd = normalize(vec3(p, -cameraZ));
        RayMarchResult res = rayMarch(ro, rd);
        vec3 color = sqrt(res.color);
        finalColor += color;
    }
    finalColor /= float(AA * AA);

    vec2 motion = vec2(fbm2(p + vec2(iTime * -0.05, iTime * -0.03))) * 3.0;
    vec3 fogColor = vec3(0.88);
    float fogIntensity = (1.0 - smoothstep(0.0, 1.2, length(p.xy)));
    float fogLevel = clamp(fbm2(p * 0.225 + motion) * fogIntensity, 0.0, 1.0);

    finalColor = mix(finalColor, fogColor, fogLevel);

    fragColor = vec4(finalColor, 1.0);
}
